#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        int temp;
        cin >> temp;
        a[i] = temp % m;
    }

    auto enumerate_subsets = [&](set<int>& sums_set, int length, int index, int current_sum = 0) {
        if (index == length) {
            sums_set.insert(current_sum);
        } else {
            enumerate_subsets(sums_set, length, index + 1, (current_sum + a[index]) % m);
            enumerate_subsets(sums_set, length, index + 1, current_sum);
        }
    };

    int split_index = n / 2;
    set<int> left_part, right_part;
    enumerate_subsets(left_part, split_index, 0);
    enumerate_subsets(right_part, n, split_index);

    vector<int> right_sorted(right_part.begin(), right_part.end());
    sort(right_sorted.begin(), right_sorted.end());

    int max_total = 0;
    for (int val : left_part) {
        int pos = (int)(std::lower_bound(right_sorted.begin(), right_sorted.end(), m - val) - right_sorted.begin());
        if (pos > 0) {
            int total_candidate = val + right_sorted[pos - 1];
            if (total_candidate > max_total) {
                max_total = total_candidate;
            }
        }
    }
    cout << max_total << "\n";
    return 0;
}
